99	  int f0, f1; float ft;
100	  if (pd.y > 0.0) { spF = mod(spF, spN); f0 = int(spF); f1 = f0 + 1; if (float(f1) >= spN) f1 = 0; ft = fract(spF); }
101	  else { spF = clamp(spF, 0.0, spN - 1.0); f0 = int(spF); f1 = min(f0 + 1, int(spN) - 1); ft = fract(spF); }
102	  f0 += int(pd.x); f1 += int(pd.x);
