1	// Chia kiểu người: đi, chạy, đứng, đi cùng, trẻ em, nón, ba lô, chụp ảnh (spec G8, §5, §7; plan Task 4)
2	import { test } from 'node:test';
3	import assert from 'node:assert/strict';
4	import { CONFIG } from '../../src/config.ts';
5	import { ppAssignKinds, PP_FLAG } from '../../src/common/people/kinds.ts';
6	
7	const M = CONFIG.people.mix;
8	const near = (got: number, want: number, what: string) => assert.ok(Math.abs(got - want) <= 2, `${what}: ${got} so với ${want.toFixed(1)}`);
9	
10	test('độ dài và cùng seed cho cùng kết quả', () => {
11	  const a = ppAssignKinds(80, 1);
12	  assert.equal(a.length, 80);
13	  assert.deepEqual(ppAssignKinds(80, 1), a);
14	  assert.notDeepEqual(ppAssignKinds(80, 2), a);
15	});
16	
17	for (const [n, seed] of [[80, 1], [46, 1965], [36, 2903], [70, 4107]] as const) test(`tỉ lệ kiểu trong ±2 người (n = ${n})`, () => {
18	  const L = ppAssignKinds(n, seed), stand = L.filter((p) => p.kind === 'stand');
19	  const comp = L.filter((p) => p.follow >= 0);
20	  near(L.filter((p) => p.kind === 'run').length, n * M.run, 'chạy');
21	  near(stand.length, n * M.stand, 'đứng');
22	  near(comp.length, n * M.companion, 'đi cùng');
23	  near(comp.filter((p) => p.scale === CONFIG.people.childScale).length, n * M.companion * M.child, 'trẻ em');
24	  near(L.filter((p) => p.flags & PP_FLAG.hat).length, n * M.hat, 'nón');
25	  near(L.filter((p) => p.flags & PP_FLAG.pack).length, n * M.pack, 'ba lô');
26	  near(stand.filter((p) => p.flags & PP_FLAG.photo).length, n * M.stand * M.photo, 'chụp ảnh');
27	});
28	
29	test('người đi cùng theo đúng người đứng trước, người đó đi bộ một mình', () => {
30	  for (const seed of [1, 2, 3, 1965, 2903, 4107]) {
31	    const L = ppAssignKinds(80, seed);
32	    L.forEach((p, i) => {
33	      if (p.follow < 0) { assert.equal(p.follow, -1); return; }
34	      assert.equal(p.follow, i - 1, `${seed}/${i}`);
35	      assert.equal(p.kind, 'walk');
36	      assert.equal(L[i - 1].kind, 'walk', `${seed}/${i}: người trước là ${L[i - 1].kind}`);
37	      assert.equal(L[i - 1].follow, -1, `${seed}/${i}: người trước cũng đi cùng`);
38	    });
39	  }
40	});
41	
42	test('{ run: false } không có người chạy, số người đứng giữ nguyên', () => {
43	  for (const seed of [1, 1965]) {
44	    const L = ppAssignKinds(34, seed, { run: false });
45	    assert.equal(L.filter((p) => p.kind === 'run').length, 0);
46	    near(L.filter((p) => p.kind === 'stand').length, 34 * M.stand, 'đứng');
47	  }
48	});
49	
50	test('trẻ em luôn là người đi cùng; chụp ảnh chỉ ở người đứng; tỉ lệ và pha hợp lệ', () => {
51	  const [a0, a1] = CONFIG.people.adultScale;
52	  for (const seed of [1, 7, 1965, 2903]) for (const p of ppAssignKinds(80, seed)) {
53	    if (p.scale === CONFIG.people.childScale) assert.ok(p.follow >= 0, 'trẻ em đi một mình');
