  const d = data(), h = (u: number) => { const s = u >> 15 ? -1 : 1, e = (u >> 10) & 31, m = u & 1023; return e === 0 ? s * m * 2 ** -24 : e === 31 ? NaN : s * (1 + m / 1024) * 2 ** (e - 15); };
